import{_ as a,o as e,c as o,a5 as d}from"./chunks/framework.BEZBAInb.js";const b=JSON.parse('{"title":"액터 상태 전환","description":"","frontmatter":{"title":"액터 상태 전환","order":4},"headers":[],"relativePath":"ko/latest/tutorial/script/actor/actor-change-state.md","filePath":"ko/latest/tutorial/script/actor/actor-change-state.md","lastUpdated":1788455378000}'),r={name:"ko/latest/tutorial/script/actor/actor-change-state.md"};function i(n,t,s,c,l,h){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="액터-상태-전환" tabindex="-1">액터 상태 전환 <a class="header-anchor" href="#액터-상태-전환" aria-label="Permalink to &quot;액터 상태 전환&quot;">​</a></h1><h2 id="기능-설명" tabindex="-1">기능 설명 <a class="header-anchor" href="#기능-설명" aria-label="Permalink to &quot;기능 설명&quot;">​</a></h2><p>지정한 액터의 상태를 전환합니다. 안전한 상태 프레임을 제공할 수 있는 캐릭터는 이전 화면과 새 화면을 실제로 블렌딩하고, 그 외 캐릭터는 페이드아웃, 상태 적용, 페이드인 방식으로 자동 대체됩니다. 전환이 끝나면 스토리 실행을 계속합니다.</p><h2 id="문법-구조" tabindex="-1">문법 구조 <a class="header-anchor" href="#문법-구조" aria-label="Permalink to &quot;문법 구조&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actor change &lt;캐릭터 이름&gt; &lt;새 상태&gt;</span></span></code></pre></div><h2 id="매개변수-설명" tabindex="-1">매개변수 설명 <a class="header-anchor" href="#매개변수-설명" aria-label="Permalink to &quot;매개변수 설명&quot;">​</a></h2><table tabindex="0"><thead><tr><th>매개변수</th><th>필수</th><th>예시</th><th>설명</th></tr></thead><tbody><tr><td>캐릭터</td><td>예</td><td>kona</td><td>상태를 전환할 액터 이름</td></tr><tr><td>새 상태</td><td>예</td><td>happy</td><td>전환할 새 상태</td></tr></tbody></table><h2 id="예시" tabindex="-1">예시 <a class="header-anchor" href="#예시" aria-label="Permalink to &quot;예시&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actor change kona happy</span></span></code></pre></div><h2 id="상태-전환-효과" tabindex="-1">상태 전환 효과 <a class="header-anchor" href="#상태-전환-효과" aria-label="Permalink to &quot;상태 전환 효과&quot;">​</a></h2><p><code>actor change</code>는 전환 방식을 자동으로 선택합니다.</p><ol><li>현재 및 대상 상태 프레임을 제공할 수 있으면 프리멀티플라이드 알파 셰이더로 픽셀을 블렌딩합니다.</li><li>안전한 상태 프레임을 제공할 수 없으면 현재 액터를 페이드아웃하고 상태를 적용한 뒤 페이드인합니다.</li><li>전환이 끝난 뒤 다음 스토리 명령을 실행합니다.</li></ol><p><code>KonadoStageController</code> 노드의 인스펙터에서 전환을 설정할 수 있습니다.</p><table tabindex="0"><thead><tr><th>속성</th><th>기본값</th><th>설명</th></tr></thead><tbody><tr><td><code>actor_state_transition_enabled</code></td><td><code>true</code></td><td>액터 상태 전환의 페이드 효과를 활성화합니다</td></tr><tr><td><code>actor_state_transition_duration</code></td><td><code>0.3</code></td><td>전체 전환 시간(초)이며, 안전 대체 경로에서는 페이드아웃과 페이드인에 절반씩 사용됩니다</td></tr></tbody></table><p><code>actor_state_transition_enabled</code>를 끄거나 <code>actor_state_transition_duration</code>을 <code>0</code>으로 설정하면 상태가 즉시 전환됩니다.</p><p>전환은 캐릭터 씬을 복제하지 않습니다. 포함된 AnimatedSprite2D 예제는 순수 텍스처 상태 프레임으로 실제 블렌딩을 수행합니다. 사용자 상태 프레임은 일부 표시 요소만이 아니라 캐릭터 전체 화면을 나타내야 합니다. 비디오, Spine, Live2D 및 완전하고 안전한 상태 프레임을 제공할 수 없는 사용자 씬은 자동으로 대체 경로를 사용하므로 스크립트, 오디오 및 동적 미디어가 두 번 실행되지 않습니다. 대상 액터가 없거나 상태를 적용할 수 없는 경우에도 명령을 완료하고 스토리를 계속합니다.</p>',16)])])}const u=a(r,[["render",i]]);export{b as __pageData,u as default};
